#!/usr/bin/env bash

set -eo pipefail

# Generate a random password
# Returns: A random password string
generate_password() {
    echo "$(dd bs=512 if=/dev/urandom count=1 2>/dev/null | LC_ALL=C tr -dc 'A-Za-z0-9' | fold -w5 | head -n4 | paste -sd '-')"
}

# Ensure PostgreSQL secrets exist
ensure_postgres_secrets() {
    echo "Ensuring secrets for PostgreSQL"

    # Use Podman secrets consistently for both internal and external databases
    # For external databases, users should create the secrets manually
    # For internal databases, secrets will be auto-generated if they don't exist

    ensure_secret "flightctl-postgresql-password" "FLIGHTCTL_POSTGRESQL_PASSWORD"
    ensure_secret "flightctl-postgresql-master-password" "FLIGHTCTL_POSTGRESQL_MASTER_PASSWORD"
    ensure_secret "flightctl-postgresql-user-password" "FLIGHTCTL_POSTGRESQL_USER_PASSWORD"
    ensure_secret "flightctl-postgresql-migrator-password" "FLIGHTCTL_POSTGRESQL_MIGRATOR_PASSWORD"
}

# Ensure KV secrets exist
ensure_kv_secrets() {
    echo "Ensuring secrets for KV"
    ensure_secret "flightctl-kv-password" "FLIGHTCTL_KV_PASSWORD"
}

ensure_delta_generation_secrets() {
    local username_secret="flightctl-delta-generation-default-repository-username"
    local password_secret="flightctl-delta-generation-default-repository-password"
    local dropin_dir="${QUADLET_SYSTEMD_DIR:-/etc/containers/systemd}/flightctl-delta-worker.container.d"
    local dropin_file="${dropin_dir}/delta-generation-repository.conf"

    if [[ -z "${DELTA_GENERATION_DEFAULT_REPOSITORY_USERNAME:-}" ||
          -z "${DELTA_GENERATION_DEFAULT_REPOSITORY_PASSWORD:-}" ]]; then
        if sudo podman secret exists "$username_secret" && sudo podman secret exists "$password_secret"; then
            sudo install -d -m 0755 "$dropin_dir"
            sudo tee "$dropin_file" >/dev/null <<EOF
# Generated by Flight Control deployment; do not edit.
[Container]
Secret=${username_secret},type=env,target=DELTA_GENERATION_DEFAULT_REPOSITORY_USERNAME
Secret=${password_secret},type=env,target=DELTA_GENERATION_DEFAULT_REPOSITORY_PASSWORD
EOF
        elif sudo test -f "$dropin_file" && sudo grep -q '^# Generated by Flight Control deployment;' "$dropin_file"; then
            sudo rm -f "$dropin_file"
        fi
        return 0
    fi

    ensure_env_secret "$username_secret" DELTA_GENERATION_DEFAULT_REPOSITORY_USERNAME
    ensure_env_secret "$password_secret" DELTA_GENERATION_DEFAULT_REPOSITORY_PASSWORD

    sudo install -d -m 0755 "$dropin_dir"
    sudo tee "$dropin_file" >/dev/null <<EOF
# Generated by Flight Control deployment; do not edit.
[Container]
Secret=${username_secret},type=env,target=DELTA_GENERATION_DEFAULT_REPOSITORY_USERNAME
Secret=${password_secret},type=env,target=DELTA_GENERATION_DEFAULT_REPOSITORY_PASSWORD
EOF
}

# Ensure a secret exists from a user-provided environment variable.
ensure_env_secret() {
    local secret_name="$1"
    local env_var_name="$2"

    if sudo podman secret exists "$secret_name"; then
        return 0
    fi
    echo "Creating secret $secret_name from $env_var_name"
    sudo -E podman secret create --env "$secret_name" "$env_var_name"
}

# Ensure a specific secret exists
# Args:
#   $1: Secret name
#   $2: Environment variable name to store the secret
ensure_secret() {
    local secret_name="$1"
    local env_var_name="$2"

    if ! sudo podman secret exists "$secret_name"; then
        echo "Creating secret $secret_name"
        if [ -z "${!env_var_name}" ]; then
            echo "Generating password for $env_var_name"
            export "$env_var_name"="$(generate_password)"
        else
            echo "Using existing environment variable $env_var_name"
        fi
        if ! sudo -E podman secret create --env "$secret_name" "$env_var_name"; then
            echo "Error creating secret $secret_name"
            return 1
        fi
    fi
    return 0
}
